import{_ as d}from"./chunks/01-editor-overview.B6DfPzWc.js";import{_ as e,o,c as r,a2 as c}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"مقدمة ومفاهيم","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/introduction.md","filePath":"ar/guide/introduction.md"}'),s={name:"ar/guide/introduction.md"};function a(n,t,l,i,g,h){return o(),r("div",null,[...t[0]||(t[0]=[c('<h1 id="مقدمة-ومفاهيم" tabindex="-1">مقدمة ومفاهيم <a class="header-anchor" href="#مقدمة-ومفاهيم" aria-label="Permalink to &quot;مقدمة ومفاهيم&quot;">​</a></h1><p>يحوّل <strong>ReelForge</strong> تسجيلاً صوتياً وملف YAML واحداً إلى فيديو شرح عمودي جاهز للنشر: بمقاس 1080×1920 وبمعدل 30 إطاراً في الثانية، وجاهز لـ <strong>TikTok</strong> و<strong>Instagram Reels</strong> و<strong>YouTube Shorts</strong>.</p><p><img src="'+d+'" alt="محرر ReelForge"></p><p>تكتب ما ستقوله جملةً جملة، وتصف ما يظهر على الشاشة و<strong>عند أي كلمة</strong> يظهر. فيحرّك ReelForge المخططات والكود والجداول والرسوم البيانية والعناوين في اللحظة التي تنطقها فيها، ويضيف ترجمة نصية تظهر كلمة بكلمة، ومؤثرات صوتية، وهوية السلسلة البصرية، ثم يعالج الصوت ويرمّز ملفات جاهزة للمنصات.</p><h2 id="أبرز-المزايا" tabindex="-1">أبرز المزايا <a class="header-anchor" href="#أبرز-المزايا" aria-label="Permalink to &quot;أبرز المزايا&quot;">​</a></h2><ul><li><strong>محرر حقيقي وبسيط.</strong> تضع المكوّنات على الإطار كما في برامج التصميم، وتعيد توقيتها على خط زمني كما في برامج المونتاج، وتعدّل كل خاصية من لوحة الخصائص، مع التراجع، وأدلة المحاذاة الذكية، ولوحة أوامر، واختصارات لوحة مفاتيح لكل شيء.</li><li><strong>متزامن مع كلماتك.</strong> تظهر العناصر عند نطق الكلمة التي تسميها. أعد تسجيل جملة فيبقى كل ما بعدها متزامناً، لأن الحركات تتبع كلماتك لا الثواني.</li><li><strong>العربية والإنجليزية.</strong> ترجمة نصية تظهر كلمة بكلمة بالإنجليزية، وبالعربية باتجاه صحيح من اليمين إلى اليسار حتى حين تتخللها مصطلحات إنجليزية: تبقى <code>الـ client</code> متماسكة، وتقع <code>؟</code> في الجهة الصحيحة.</li><li><strong>قوالب لقطاعات كثيرة.</strong> تقدّم الحزم القطاعية (الرعاية الصحية، والعقارات، والخدمات اللوجستية، والتعليم، والمالية وغيرها) قوالب جاهزة: تملأ بضعة حقول فتحصل على حلقة مصمَّمة.</li><li><strong>يعمل مع مساعدي الذكاء الاصطناعي (اختياري).</strong> يتيح خادم MCP مدمج وواجهة REST لـ Claude وCursor وCopilot وCodex وGemini وغيرها من العملاء أن تكتب النصوص وتبني المشاهد وتفحص الإطارات نيابةً عنك.</li><li><strong>مكوّنات متحركة</strong> للشرح: عُقد وأسهم تتحرك عليها حزم البيانات، وكود يكتب نفسه، ورسوم بيانية، وخطوات ومسارات، وجداول، وخطوط زمنية، ومقاييس، وعدّادات، ونموذج هاتف، وأختام…</li><li><strong>صوت احترافي</strong>: مؤثرات صوتية مولّدة إجرائياً مع كل ضربة وانتقال، وصوت معالَج إلى −14 LUFS (مستوى الجهارة الذي تستهدفه المنصات)، وخفض تلقائي للمؤثرات تحت الصوت.</li><li><strong>ملفات جاهزة للمنصات</strong>: ملف MP4 رئيسي للأرشفة، وملف MP4 للنشر لا يتجاوز حد الرفع الذي تختاره، وملف ترجمة SRT، وورقة لقطات (contact sheet)، وملف <code>publish.md</code> فيه نص المنشور والوسوم والتعليق المثبّت.</li><li><strong>لا ذكاء اصطناعي في محرك الرسم.</strong> يرسم الإطارات محرك حتمي ويرمّزها FFmpeg. لا يولّد أصواتاً ولا صوراً أبداً: صوتك وكلماتك وتصميمك، بالنتيجة نفسها في كل مرة.</li><li><strong>أدوات مساعدة محلية واختيارية.</strong> تحدد محاذاة الكلام بداية كل سطر وكل كلمة من تسجيلك، ويقترح مساعد المشاهد مكوّناً للسطر. كلاهما يعمل على جهازك، ويمكنك دائماً أن تحدد الـ cues بالسمع وتصمم المشاهد بنفسك بدلاً منهما.</li><li><strong>دون إنترنت وبخصوصية تامة.</strong> كل شيء يعمل على جهازك: لا حساب ولا اشتراك ولا رفع ملفات. ينزّل الأمر <code>reelforge align --setup</code> نماذج الكلام الاختيارية مرة واحدة، وبعدها يعمل كل شيء دون اتصال.</li><li><strong>نتائج ثابتة.</strong> المدخلات نفسها تنتج دائماً الإطارات نفسها.</li></ul><h2 id="المفاهيم-الأساسية" tabindex="-1">المفاهيم الأساسية <a class="header-anchor" href="#المفاهيم-الأساسية" aria-label="Permalink to &quot;المفاهيم الأساسية&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المصطلح</th><th>المعنى</th></tr></thead><tbody><tr><td><strong>الحلقة</strong> (episode)</td><td>فيديو واحد: مجلد <code>episodes/&lt;id&gt;/</code> فيه <code>episode.yaml</code> وتسجيلك <code>voice.wav</code> والملف <code>cues.json</code> والمخرجات في <code>out/</code>.</td></tr><tr><td><strong>سطر النص</strong></td><td>جملة منطوقة واحدة. تأخذ الأسطر المعرّفات <code>l1</code> و<code>l2</code>… بالترتيب، ومنها تُبنى الترجمة النصية.</td></tr><tr><td><strong>الـ cue</strong></td><td>لحظة بداية السطر في تسجيلك. تأتي الـ cues من المحاذاة التلقائية، أو من التحديد بالسمع، أو من تقدير قبل التسجيل.</td></tr><tr><td><strong>المشهد</strong></td><td>مجموعة عناصر على الشاشة. يبدأ المشهد عند سطر (<code>at: l3</code>) وينتهي حيث يبدأ المشهد التالي.</td></tr><tr><td><strong>العنصر</strong></td><td>مكوّن واحد داخل مشهد، له خصائص (<code>props</code>) وصندوق (<code>place</code>) ووقت دخول ووقت خروج.</td></tr><tr><td><strong>المكوّن</strong></td><td>لبنة بناء مثل <code>title</code> و<code>node</code> و<code>arrow</code> و<code>code</code> و<code>bar-chart</code> و<code>steps</code>. خصائصه صارمة وموثقة في مرجع المكوّنات.</td></tr><tr><td><strong>تعبير الزمن</strong></td><td>زمن مكتوب نسبةً إلى كلماتك: <code>l3</code> و<code>l3.end</code> و<code>l3:&#39;bucket&#39;</code> و<code>@scene.end</code>، مع إزاحات مثل <code>+0.4</code>. والكلمات تصمد أمام إعادة التسجيل.</td></tr><tr><td><strong>الثيم</strong></td><td>الألوان والخطوط والأحجام وإعدادات الحركة في <code>themes/&lt;name&gt;.theme.yaml</code>.</td></tr><tr><td><strong>الـ preset</strong></td><td>تخطيط المنصة (<code>tiktok</code> أو <code>reels</code> أو <code>shorts</code>): مواضع الترويسة والمسرح والترجمة النصية، والمناطق الآمنة للمنصة.</td></tr><tr><td><strong>الحزمة والقالب</strong></td><td>تجمع الحزمة القطاعية ثيماً وقوالب. والقالب حلقة فيها حقول مسمّاة (slots) تملؤها أنت.</td></tr><tr><td><strong>الـ Timeline</strong></td><td>الحلقة بعد تحويلها (compile) وحساب كل أزمنتها. هي العقد الوحيد بين الـ compiler ومحرك الرسم، ولهذا تبقى النتيجة قابلة للتكرار.</td></tr></tbody></table><h2 id="كيف-يُصنع-الفيديو" tabindex="-1">كيف يُصنع الفيديو <a class="header-anchor" href="#كيف-يُصنع-الفيديو" aria-label="Permalink to &quot;كيف يُصنع الفيديو&quot;">​</a></h2><ol><li><strong>ابدأ</strong> من قالب (<code>reelforge new &lt;id&gt; --pack &lt;pack&gt; --template &lt;template&gt;</code>)، أو من حلقة فارغة (<code>reelforge new &lt;id&gt;</code>)، أو من لوحة التحكم.</li><li><strong>اكتب النص</strong>: جملة منطوقة قصيرة في كل سطر، بمعدل 2.3 كلمة في الثانية تقريباً.</li><li><strong>صمّم المشاهد</strong> في المحرر أو في YAML، بحيث يدخل كل عنصر عند الكلمة التي تسميه.</li><li><strong>سجّل</strong> صوتك. يحدد الأمر <code>reelforge align</code> بداية كل سطر وكل كلمة، ثم تراجعها بالسمع في وضع Cues.</li><li><strong>راجع</strong>: يأتي كل فحص (التداخل، والمناطق الآمنة، وتجاوز النص لصندوقه، وسرعة الإلقاء) مع تلميح لإصلاحه.</li><li><strong>صدّر</strong> الفيديو، ثم ارفع ملف النشر مع النصوص الموجودة في <code>publish.md</code>.</li></ol><p>يشرح <a href="./quick-start.html">البدء السريع</a> هذه الخطوات في عشر دقائق تقريباً.</p><h2 id="محتويات-المستودع" tabindex="-1">محتويات المستودع <a class="header-anchor" href="#محتويات-المستودع" aria-label="Permalink to &quot;محتويات المستودع&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المجلد أو الملف</th><th>المحتوى</th></tr></thead><tbody><tr><td><code>install.bat</code> (<code>install.ps1</code>) و<code>install.sh</code></td><td>مثبّتات بأمر واحد لـ Windows وmacOS وLinux</td></tr><tr><td><code>start.bat</code> و<code>start.sh</code> و<code>ReelForge.command</code></td><td>فتح لوحة التحكم</td></tr><tr><td><code>reelforge.cmd</code> و<code>reelforge</code></td><td>واجهة سطر الأوامر</td></tr><tr><td><code>examples/season1/</code></td><td>تسع حلقات كاملة كأمثلة بالإنجليزية (سلسلة “System Design”)</td></tr><tr><td><code>examples/season1-arabic/</code></td><td>السلسلة نفسها بالعربية مع المصطلحات التقنية بالإنجليزية</td></tr><tr><td><code>examples/promo/intro/</code></td><td>فيديو تعريفي بـ ReelForge مدته 45 ثانية يستعرض الحركات</td></tr><tr><td><code>packs/</code></td><td>الحزم القطاعية: ملفات التعريف (manifest) والقوالب وحلقات الأمثلة</td></tr><tr><td><code>skills/</code></td><td>أدلة مهام لمساعدي الذكاء الاصطناعي (بصيغة Agent Skills)</td></tr><tr><td><code>AGENTS.md</code> و<code>CLAUDE.md</code> و<code>GEMINI.md</code>…</td><td>تعليمات لمساعدي الذكاء الاصطناعي (راجع <a href="./ai.html">التكامل مع الذكاء الاصطناعي</a>)</td></tr><tr><td><code>themes/</code> و<code>presets/</code></td><td>ثيمات بصرية وتخطيطات منصات قابلة للتعديل</td></tr><tr><td><code>docs/</code> و<code>documentation/</code></td><td>هذا التوثيق (مصدر الموقع، ونسخة تعمل دون اتصال)</td></tr><tr><td><code>packages/</code></td><td>الكود المصدري الكامل بلغة TypeScript</td></tr><tr><td><code>LICENSE</code> و<code>NOTICE</code> و<code>THIRD-PARTY-NOTICES.md</code></td><td>ترخيص Apache-2.0 والإشعارات وحقوق المكوّنات الخارجية</td></tr></tbody></table><h2 id="المتطلبات" tabindex="-1">المتطلبات <a class="header-anchor" href="#المتطلبات" aria-label="Permalink to &quot;المتطلبات&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>الحد الأدنى</th><th>الموصى به</th></tr></thead><tbody><tr><td>نظام التشغيل</td><td>Windows 10 أو macOS 13 أو Ubuntu 22.04 (أو أي Linux حديث)</td><td>Windows 11 أو macOS 14+ أو Ubuntu 24.04</td></tr><tr><td>المعالج والذاكرة</td><td>4 أنوية و8 GB</td><td>8 خيوط أو أكثر و16 GB (يتسارع التصدير بزيادة الأنوية)</td></tr><tr><td>القرص</td><td>2 GB متاحة (مع ~2 GB مؤقتة لكل تصدير)</td><td>SSD</td></tr><tr><td>البرمجيات</td><td><strong>Node.js 22 LTS</strong> و<strong>ffmpeg 6+</strong></td><td>يثبّتها المثبّت تلقائياً حيثما أمكن</td></tr></tbody></table><p>يستغرق تصدير حلقة مدتها دقيقتان من 5 إلى 10 دقائق تقريباً على حاسوب محمول بثمانية خيوط.</p>',16)])])}const b=e(s,[["render",a]]);export{u as __pageData,b as default};
